{"path":"assets/css/styles.css","content":"/* Editorial — high-contrast, strong typographic scale */
:root{--bg:#ffffff;--muted:#6b6b6b;--accent:#0b5f6e;--accent-2:#ffb86b;--dark:#0b0b0b;--pale:#f7f9fa}
*{box-sizing:border-box}
html,body{height:100%}
body{font-family:Georgia, 'Times New Roman', serif;color:var(--dark);margin:0;background:var(--bg);line-height:1.5}
.wrap{max-width:980px;margin:0 auto;padding:2rem}
.site-header{border-bottom:1px solid #eee;background:linear-gradient(180deg,rgba(255,255,255,.9),rgba(255,255,255,1));position:sticky;top:0;z-index:10}
.site-header .wrap{display:flex;align-items:center;justify-content:space-between}
.brand{display:flex;align-items:center;text-decoration:none;color:inherit}
.brand-avatar{width:56px;height:56px;margin-right:12px}
.brand-text .business{display:block;font-weight:700;font-size:1.05rem}
.brand-text .tag{font-size:0.85rem;color:var(--muted)}
.nav-toggle{display:none;background:none;border:1px solid var(--muted);padding:6px 10px;border-radius:4px}
.nav-list{list-style:none;display:flex;gap:1rem;margin:0;padding:0}
.nav-list a{color:var(--dark);text-decoration:none;padding:8px}
.nav-list a.primary{background:var(--accent);color:#fff;border-radius:4px;padding:8px 12px}
.hero{padding:4rem 0}
.hero-grid{display:grid;grid-template-columns:1fr 360px;gap:2rem;align-items:center}
.eyebrow{color:var(--accent-2);font-weight:700;letter-spacing:0.06em}
.headline{font-size:2.25rem;margin:0 0 1rem}
.lede{color:var(--muted);margin-bottom:1rem}
.hero-art img{width:100%;height:auto;border-radius:8px;box-shadow:0 10px 30px rgba(11,95,110,0.08)}
.btn{display:inline-block;border-radius:6px;padding:10px 16px;text-decoration:none;border:1px solid transparent}
.btn-primary{background:var(--accent);color:white}
.btn-outline{background:transparent;border-color:var(--accent);color:var(--accent)}
.section{padding:3rem 0}
.pale{background:var(--pale)}
.dark{background:#081016;color:#e9f6f7}
.section-title{font-size:1.15rem;margin:0 0 0.75rem;font-weight:700}
.values-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1.25rem}
.methods{padding-top:0}
.method-list{list-style:none;padding:0;margin:0;display:grid;gap:0.5rem}
.objections-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem}
.testimonials{display:flex;gap:1rem}
blockquote{background:#fff;border-radius:8px;padding:1rem;flex:1;box-shadow:0 6px 18px rgba(11,95,110,0.05)}
blockquote p{margin:0 0 .5rem}
blockquote cite{font-size:0.85rem;color:var(--muted)}
.lead-form{display:flex;gap:.5rem;margin-top:1rem}
.lead-form input{flex:1;padding:10px;border:1px solid #ddd;border-radius:6px}
.callout{background:linear-gradient(90deg,rgba(11,95,110,0.95),rgba(11,95,110,0.85));color:white}
.callout-grid{display:flex;justify-content:space-between;align-items:center}
.footer-grid{display:grid;grid-template-columns:1fr 1fr 1fr;gap:1rem;padding:2rem 0}
.fineprint{border-top:1px solid #eee;padding:1rem 0;color:var(--muted);font-size:0.9rem}
.small{font-size:0.9rem}
.muted{color:var(--muted)}
.modal{position:fixed;inset:0;display:none;align-items:center;justify-content:center;background:rgba(0,0,0,0.45)}
.modal[aria-hidden="false"]{display:flex}
.modal-dialog{background:#fff;padding:1.25rem;border-radius:8px;max-width:520px;width:90%}
.modal-close{background:none;border:0;float:right;font-weight:700}
@media(max-width:880px){
  .hero-grid{grid-template-columns:1fr}
  .values-grid,.objections-grid{grid-template-columns:1fr}
  .nav-list{display:none;position:absolute;right:1rem;top:64px;background:#fff;padding:1rem;border-radius:8px;box-shadow:0 6px 20px rgba(0,0,0,.08)}
  .nav-toggle{display:inline-block}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Basic interactive behaviors: nav toggle, lead magnet form, modal
  var navToggle = document.getElementById('navToggle');
  var navList = document.getElementById('navList');
  if(navToggle){
    navToggle.addEventListener('click',function(){
      var expanded = this.getAttribute('aria-expanded') === 'true';
      this.setAttribute('aria-expanded', String(!expanded));
      if(navList.style.display === 'block'){ navList.style.display = ''; } else { navList.style.display = 'block'; }
    });
  }

  var leadBtn = document.getElementById('leadMagnetBtn');
  var modal = document.getElementById('modal');
  var modalContent = document.getElementById('modalContent');
  var modalClose = document.getElementById('modalClose');
  function openModal(html){
    modalContent.innerHTML = html;
    modal.setAttribute('aria-hidden','false');
  }
  function closeModal(){ modal.setAttribute('aria-hidden','true'); }
  if(leadBtn){ leadBtn.addEventListener('click', function(){ openModal('<h3>Get the worksheet</h3><p>Enter your email in the form below to receive a short PDF with a guided exercise.</p><p><a href="#leadForm">Go to sign-up form ↓</a></p>'); }); }
  if(modalClose){ modalClose.addEventListener('click', closeModal); }
  modal.addEventListener('click', function(e){ if(e.target===modal){ closeModal(); } });

  var leadForm = document.getElementById('leadForm');
  if(leadForm){
    leadForm.addEventListener('submit', function(e){
      e.preventDefault();
      var email = document.getElementById('leadEmail').value.trim();
      if(!email || email.indexOf('@')===-1){ openModal('<p>Please enter a valid email address.</p>'); return; }
      // Simulated send — in real deployment, hook to email provider
      openModal('<h3>Worksheet on its way</h3><p>Thank you. The worksheet will be sent to '+email+'. If you don\'t receive it within an hour, email {{EMAIL}}.</p>');
      leadForm.reset();
    });
  }

  // Year in footer
  var y = new Date().getFullYear();
  var yearNode = document.getElementById('year');
  if(yearNode) yearNode.textContent = y;
})();
"} 
